input.command:
cd /app && python3 -c "
import json,subprocess,collections
pats={p['id']:p for p in json.load(open('work/patients.json'))['resources']}
living={i for i,p in pats.items() if not p.get('deceasedDateTime')}
e=json.load(open('work/ecgs.json'))['ecgs']
bypat=collections.defaultdict(list)
own={}
for x in e:
    bypat[x['patient']].append(x); own[x['ecg']]=x['patient']
need={}
for i,v in bypat.items():
    if i in living:
        v.sort(key=lambda x:x['time']); need[i]=v[-1]['ecg']
got=json.loads(subprocess.run(['clinic','interpretations'],capture_output=True,text=True).stdout)['interpretations']
gecg={g['ecg'] for g in got}
print('need',len(need),'got',len(got),'unique',len(gecg))
print('missing:',{p:x for p,x in need.items() if x not in gecg})
print('extra:',[x for x in gecg if x not in set(need.values())])
# sanity on fields
for g in got:
    if g['rhythm']!='AF' and g['pr_ms'] is None: print('no PR', g['ecg'])
    if g['rhythm']=='AF' and g['pr_ms'] is not None: print('AF has PR', g['ecg'])
    for k in ['ventricular_rate','qrs_ms','qtc_ms','axis','explanation']:
        if g.get(k) in (None,''): print('missing',k,g['ecg'])
"
echo "=== items ==="
clinic items | python3 -c "
import json,sys
d=json.load(sys.stdin)
print(len(d['items']))
for i in d['items']: print(i['id'], i['patient'][:8], i['category'], i['reason'], i['status'])
"

